-- LEXA Electronics Catalogue V2 Phase 1: additive, read-safe taxonomy and master data.
-- No UPDATE/DELETE of any existing category, product, variant, serial, lot or ledger row.
ALTER TABLE public.categories ADD COLUMN catalog_code text;
ALTER TABLE public.categories ADD COLUMN taxonomy_version integer;
ALTER TABLE public.categories ADD CONSTRAINT lexa_catalog_code_format
 CHECK (catalog_code IS NULL OR catalog_code ~ '^(ELEC|CUSTOM)\.[A-Z0-9_]+(\.[A-Z0-9_]+){0,3}$');
CREATE UNIQUE INDEX categories_catalog_code_tenant_idx ON public.categories(tenant_id,upper(catalog_code)) WHERE catalog_code IS NOT NULL;
CREATE INDEX categories_parent_browse_idx ON public.categories(tenant_id,parent_id,name);

ALTER TABLE public.catalog_device_models ADD COLUMN family_code text;
ALTER TABLE public.catalog_device_models ADD COLUMN reference_specs jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.catalog_device_models ADD COLUMN reference_version integer NOT NULL DEFAULT 0 CHECK(reference_version>=0);
ALTER TABLE public.catalog_device_models ADD COLUMN provenance jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.catalog_device_models ADD COLUMN review_status text NOT NULL DEFAULT 'draft' CHECK(review_status IN ('draft','reviewed','rejected'));
ALTER TABLE public.catalog_device_models ADD COLUMN reviewed_by_user_id uuid REFERENCES public.users(id) ON DELETE RESTRICT;
ALTER TABLE public.catalog_device_models ADD COLUMN reviewed_at timestamptz(3);
ALTER TABLE public.catalog_device_models ADD CONSTRAINT catalog_model_review_consistent
 CHECK ((review_status='reviewed' AND reviewed_at IS NOT NULL AND reviewed_by_user_id IS NOT NULL)
     OR (review_status<>'reviewed' AND reviewed_at IS NULL AND reviewed_by_user_id IS NULL));
CREATE INDEX catalog_device_models_family_idx ON public.catalog_device_models(tenant_id,family_code,review_status);

CREATE TABLE public.catalog_category_aliases (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,
 category_id uuid NOT NULL,alias_text text NOT NULL CHECK(length(btrim(alias_text)) BETWEEN 1 AND 300),
 normalized_alias text NOT NULL CHECK(length(normalized_alias) BETWEEN 1 AND 300),
 source_version integer,created_by_user_id uuid NOT NULL,created_at timestamptz(3) NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,normalized_alias),
 FOREIGN KEY(tenant_id,category_id) REFERENCES public.categories(tenant_id,id) ON DELETE RESTRICT,
 FOREIGN KEY(created_by_user_id) REFERENCES public.users(id) ON DELETE RESTRICT
);
CREATE INDEX catalog_category_aliases_category_idx ON public.catalog_category_aliases(tenant_id,category_id);

CREATE TABLE public.catalog_brand_aliases (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,
 brand_id uuid NOT NULL,alias text NOT NULL CHECK(length(btrim(alias)) BETWEEN 1 AND 100),
 normalized_alias text NOT NULL CHECK(length(normalized_alias) BETWEEN 1 AND 100),
 created_by_user_id uuid NOT NULL,created_at timestamptz(3) NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,normalized_alias),
 FOREIGN KEY(tenant_id,brand_id) REFERENCES public.catalog_brands(tenant_id,id) ON DELETE RESTRICT,
 FOREIGN KEY(created_by_user_id) REFERENCES public.users(id) ON DELETE RESTRICT
);
CREATE INDEX catalog_brand_aliases_brand_idx ON public.catalog_brand_aliases(tenant_id,brand_id);

CREATE TABLE public.catalog_brand_merge_proposals (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,
 source_brand_id uuid NOT NULL,target_brand_id uuid NOT NULL,
 rationale text CHECK(rationale IS NULL OR length(rationale)<=1000),
 status text NOT NULL DEFAULT 'proposed' CHECK(status IN ('proposed','rejected','approved_for_review')),
 proposed_by_user_id uuid NOT NULL,created_at timestamptz(3) NOT NULL DEFAULT now(),
 CHECK(source_brand_id<>target_brand_id),
 UNIQUE(tenant_id,source_brand_id,target_brand_id,status),
 FOREIGN KEY(tenant_id,source_brand_id) REFERENCES public.catalog_brands(tenant_id,id) ON DELETE RESTRICT,
 FOREIGN KEY(tenant_id,target_brand_id) REFERENCES public.catalog_brands(tenant_id,id) ON DELETE RESTRICT,
 FOREIGN KEY(proposed_by_user_id) REFERENCES public.users(id) ON DELETE RESTRICT
);

CREATE TABLE public.catalog_model_spec_revisions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,
 model_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),
 family_code text NOT NULL,reference_specs jsonb NOT NULL DEFAULT '{}'::jsonb,
 provenance jsonb NOT NULL DEFAULT '{}'::jsonb,
 review_status text NOT NULL DEFAULT 'draft' CHECK(review_status IN ('draft','reviewed','rejected')),
 created_by_user_id uuid NOT NULL,created_at timestamptz(3) NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,model_id,version),
 FOREIGN KEY(tenant_id,model_id) REFERENCES public.catalog_device_models(tenant_id,id) ON DELETE RESTRICT,
 FOREIGN KEY(created_by_user_id) REFERENCES public.users(id) ON DELETE RESTRICT
);

-- Global, public read-only policy definitions; never mix this with tenant stock data.
CREATE TABLE public.catalog_family_policies (
 family_code text NOT NULL, policy_version integer NOT NULL CHECK(policy_version>0),
 manifest_version integer NOT NULL,checksum text NOT NULL CHECK(length(checksum)=64),
 policy jsonb NOT NULL,published_at timestamptz(3) NOT NULL DEFAULT now(),
 PRIMARY KEY(family_code,policy_version)
);

-- Prevent alias/canonical brand collisions, including simultaneous alias + brand writers.
-- Historical conflicting brand spellings are NOT rewritten or deleted.
CREATE OR REPLACE FUNCTION public.lexa_guard_new_brand_alias_collisions() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE normalized text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(NEW.tenant_id::text),hashtext('lexa_brand_alias_lock'));
  IF TG_TABLE_NAME='catalog_brands' THEN
    normalized := lower(regexp_replace(btrim(NEW.name),'[[:space:]]+',' ','g'));
    IF EXISTS(SELECT 1 FROM public.catalog_brand_aliases a
             WHERE a.tenant_id=NEW.tenant_id AND a.normalized_alias=normalized) THEN
      RAISE EXCEPTION 'LEXA_BRAND_ALIAS_COLLISION: a registered alias already owns that name' USING ERRCODE='23505';
    END IF;
  ELSE
    normalized := lower(regexp_replace(btrim(NEW.alias),'[[:space:]]+',' ','g'));
    IF NEW.normalized_alias<>normalized THEN
      RAISE EXCEPTION 'LEXA_BRAND_ALIAS_INVALID: normalized alias mismatch' USING ERRCODE='23514';
    END IF;
    IF EXISTS(SELECT 1 FROM public.catalog_brands b
             WHERE b.tenant_id=NEW.tenant_id
             AND lower(regexp_replace(btrim(b.name),'[[:space:]]+',' ','g'))=normalized) THEN
      RAISE EXCEPTION 'LEXA_BRAND_ALIAS_COLLISION: brand already owns that name' USING ERRCODE='23505';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER lexa_new_brand_no_alias_collision BEFORE INSERT OR UPDATE OF name ON public.catalog_brands
 FOR EACH ROW EXECUTE FUNCTION public.lexa_guard_new_brand_alias_collisions();
CREATE TRIGGER lexa_brand_alias_guard BEFORE INSERT OR UPDATE OF alias,normalized_alias ON public.catalog_brand_aliases
 FOR EACH ROW EXECUTE FUNCTION public.lexa_guard_new_brand_alias_collisions();

-- Published model reference snapshots and global policy versions are append-only.
CREATE OR REPLACE FUNCTION public.lexa_reject_catalogue_version_rewrite() RETURNS trigger
LANGUAGE plpgsql AS $$ BEGIN
 RAISE EXCEPTION 'LEXA_CATALOGUE_VERSION_IMMUTABLE' USING ERRCODE='23514';
END $$;
CREATE TRIGGER lexa_catalog_model_versions_append_only BEFORE UPDATE OR DELETE ON public.catalog_model_spec_revisions
 FOR EACH ROW EXECUTE FUNCTION public.lexa_reject_catalogue_version_rewrite();
CREATE TRIGGER lexa_catalog_policies_append_only BEFORE UPDATE OR DELETE ON public.catalog_family_policies
 FOR EACH ROW EXECUTE FUNCTION public.lexa_reject_catalogue_version_rewrite();

-- Tenant isolation must be explicit on every new tenant-owned table.
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['catalog_category_aliases','catalog_brand_aliases',
  'catalog_brand_merge_proposals','catalog_model_spec_revisions'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY tenant_scope ON public.%I FOR ALL USING (tenant_id::text = NULLIF(current_setting(''app.tenant_id'',true),'''')) WITH CHECK (tenant_id::text = NULLIF(current_setting(''app.tenant_id'',true),''''))',t);
  EXECUTE format('GRANT SELECT,INSERT ON public.%I TO lexa_app_runtime',t);
 END LOOP;
END $$;
GRANT SELECT ON public.catalog_family_policies TO lexa_app_runtime;
ALTER TABLE public.catalog_family_policies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.catalog_family_policies FORCE ROW LEVEL SECURITY;
CREATE POLICY published_policy_read ON public.catalog_family_policies FOR SELECT USING(true);
-- Authoritative backup inventory must include all new tenant-owned records.
INSERT INTO public.platform_backup_inventory(table_name,disposition,domain,rationale,dependency_order) VALUES
('catalog_category_aliases','authoritative','catalog','Tenant category aliases and historical path mapping',55),
('catalog_brand_aliases','authoritative','catalog','Tenant brand alias ownership',54),
('catalog_brand_merge_proposals','authoritative','catalog','Non-destructive proposed manufacturer merges',54),
('catalog_model_spec_revisions','authoritative','catalog','Immutable manufacturer model specification versions',56),
('catalog_family_policies','reconstructed','catalog','Published canonical policy manifest generated from source',10)
ON CONFLICT (table_name) DO UPDATE SET disposition=EXCLUDED.disposition,domain=EXCLUDED.domain,rationale=EXCLUDED.rationale,dependency_order=EXCLUDED.dependency_order;

